
import React, { useEffect, useMemo, useState } from 'react';
import './style.css';

const API = 'http://localhost:5000/api';

const resources = {
  recipes: {
    title: 'My Recipes',
    subtitle: 'Create and organize your favourite recipes.',
    path: 'recipes',
    fields: [
      { key: 'title', label: 'Recipe name', required: true },
      { key: 'description', label: 'Description', type: 'textarea' },
      { key: 'instructions', label: 'Preparation instructions', type: 'textarea' },
      { key: 'prep_minutes', label: 'Preparation time (minutes)', type: 'number' },
      { key: 'servings', label: 'Number of servings', type: 'number' }
    ]
  },
  ingredients: {
    title: 'Ingredients',
    subtitle: 'Manage the ingredients used in your recipes.',
    path: 'ingredients',
    fields: [
      { key: 'name', label: 'Ingredient name', required: true },
      { key: 'unit', label: 'Unit (g, ml, pieces...)' }
    ]
  },
  'meal-plans': {
    title: 'Meal Planner',
    subtitle: 'Organize your meals throughout the week.',
    path: 'meal-plans',
    fields: [
      { key: 'plan_date', label: 'Date', type: 'date', required: true },
      { key: 'meal_type', label: 'Meal type', type: 'select', options: ['Breakfast', 'Lunch', 'Dinner', 'Snack'] },
      { key: 'recipe_id', label: 'Choose a recipe', type: 'recipe', required: true }
    ]
  },
  'shopping-list': {
    title: 'Shopping List',
    subtitle: 'Keep track of everything you need to buy.',
    path: 'shopping-list',
    fields: [
      { key: 'item_name', label: 'Item name', required: true },
      { key: 'quantity', label: 'Quantity', type: 'number' },
      { key: 'unit', label: 'Unit' },
      { key: 'is_purchased', label: 'Purchased?', type: 'boolean' }
    ]
  }
};

const mongoResources = {
  reviews: {
    title: 'Recipe Reviews',
    subtitle: 'Save ratings and comments about your recipes.',
    path: 'reviews',
    fields: [
      { key: 'recipeId', label: 'Recipe', type: 'recipe', required: true },
      { key: 'rating', label: 'Rating (1–5)', type: 'number', required: true },
      { key: 'comment', label: 'Comment', type: 'textarea' }
    ]
  },
  carts: {
    title: 'Shopping Carts',
    subtitle: 'Keep shopping items together.',
    path: 'carts',
    fields: [
      { key: 'cartName', label: 'Cart name', required: true },
      { key: 'itemsText', label: 'Items (one per line)', type: 'textarea', required: true }
    ]
  },
  notifications: {
    title: 'Notifications',
    subtitle: 'View and manage your application notifications.',
    path: 'notifications',
    fields: [
      { key: 'message', label: 'Message', type: 'textarea', required: true },
      { key: 'type', label: 'Type', type: 'select', options: ['info', 'success', 'warning'] },
      { key: 'read', label: 'Read?', type: 'boolean' }
    ]
  },
  'activity-logs': {
    title: 'Activity History',
    subtitle: 'Review the actions recorded by the application.',
    path: 'activity-logs',
    fields: [
      { key: 'action', label: 'Action', required: true },
      { key: 'entity', label: 'Entity' },
      { key: 'entityId', label: 'Entity ID', type: 'number' },
      { key: 'detailsText', label: 'Details (JSON or text)', type: 'textarea' }
    ]
  }
};

const emptyForm = fields =>
  Object.fromEntries(fields.map(field => [field.key, field.type === 'boolean' ? false : '']));

const MEAL_PLANNER_LOGO = 'data:image/png;base64,';

function MealPlannerLogo({ size = 180, className = '' }) {
  return (
    <img
      src={MEAL_PLANNER_LOGO}
      width={size}
      height={size}
      className={className}
      alt="Meal Planner — Plan • Cook • Enjoy"
      style={{ width: size, height: size, objectFit: 'contain', display: 'block' }}
    />
  );
}

function App() {
  const [token, setToken] = useState(localStorage.getItem('mp_token') || '');
  const [user, setUser] = useState(null);
  const [authMode, setAuthMode] = useState('login');
  const [authForm, setAuthForm] = useState({ name: '', email: '', password: '' });
  const [section, setSection] = useState('dashboard');
  const [rows, setRows] = useState([]);
  const [recipes, setRecipes] = useState([]);
  const [form, setForm] = useState({});
  const [editing, setEditing] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [dashboard, setDashboard] = useState({
    recipes: 0, ingredients: 0, plans: 0, shopping: 0
  });

  const currentConfig = resources[section] || mongoResources[section];

  const isSqlSection = Boolean(resources[section]);
  const isMongoSection = Boolean(mongoResources[section]);

  const notify = (text, isError = false) => {
    setMessage(isError ? '' : text);
    setError(isError ? text : '');
    window.setTimeout(() => {
      setMessage('');
      setError('');
    }, 4500);
  };

  const call = async (path, options = {}) => {
    const response = await fetch(`${API}${path}`, {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
        ...(options.headers || {})
      }
    });

    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      throw new Error(data.error || 'Something went wrong.');
    }

    return data;
  };

  const loadRecipes = async () => {
    const data = await call('/recipes');
    setRecipes(data);
    return data;
  };

  const loadRows = async () => {
    if (!currentConfig) return;

    setLoading(true);
    try {
      if (section === 'recipes') {
        const data = await call('/recipes');
        setRecipes(data);
        setRows(data);
      } else {
        const data = await call(`/${currentConfig.path}`);
        setRows(data);
      }
    } catch (err) {
      notify(err.message, true);
    } finally {
      setLoading(false);
    }
  };

  const loadDashboard = async () => {
    try {
      const [recipeData, ingredientData, planData, shoppingData] = await Promise.all([
        call('/recipes'),
        call('/ingredients'),
        call('/meal-plans'),
        call('/shopping-list')
      ]);

      setDashboard({
        recipes: recipeData.length,
        ingredients: ingredientData.length,
        plans: planData.length,
        shopping: shoppingData.filter(item => !item.is_purchased).length
      });
      setRecipes(recipeData);
    } catch (err) {
      notify(err.message, true);
    }
  };

  useEffect(() => {
    if (!token) return;

    const initialize = async () => {
      try {
        const account = await call('/me');
        setUser(account);
      } catch {
        localStorage.removeItem('mp_token');
        setToken('');
        setUser(null);
      }
    };

    initialize();
  }, [token]);

  useEffect(() => {
    if (!token || !user) return;

    if (section === 'dashboard') {
      loadDashboard();
    } else if (section === 'recipe-ingredients') {
      loadRecipes();
    } else if (currentConfig) {
      loadRows();
      if (section !== 'recipes') loadRecipes();
    }
  }, [section, token, user]);

  const handleAuth = async event => {
    event.preventDefault();
    setError('');

    try {
      const endpoint = authMode === 'login' ? '/auth/login' : '/auth/register';
      const data = await fetch(`${API}${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(authForm)
      }).then(async response => {
        const result = await response.json();
        if (!response.ok) throw new Error(result.error || 'Authentication failed.');
        return result;
      });

      localStorage.setItem('mp_token', data.token);
      setToken(data.token);
      setUser(data.user);
      setSection('dashboard');
      notify('Welcome to Meal Planner!');
    } catch (err) {
      setError(err.message);
    }
  };

  const logout = () => {
    localStorage.removeItem('mp_token');
    setToken('');
    setUser(null);
    setRows([]);
    setSection('dashboard');
  };

  const openCreate = () => {
    setEditing(null);
    setForm(emptyForm(currentConfig.fields));
    setShowForm(true);
  };

  const openEdit = row => {
    setEditing(row.id || row._id);
    const values = {};

    currentConfig.fields.forEach(field => {
      let value = row[field.key] ?? '';

      if (section === 'carts' && field.key === 'cartName') {
        const lines = String(row.itemsText || '').split(/\r?\n/).map(line => line.trim()).filter(Boolean);
        value = lines.length > 1 ? lines[0] : 'My Shopping Cart';
      }

      if (section === 'carts' && field.key === 'itemsText') {
        const lines = String(row.itemsText || '').split(/\r?\n/).map(line => line.trim()).filter(Boolean);
        value = lines.length > 1 ? lines.slice(1).join('\n') : String(row.itemsText || '');
      }

      if (field.key === 'recipe_id' || field.key === 'recipeId') {
        value = String(value);
      }

      if (field.type === 'boolean') {
        value = Boolean(value);
      }

      values[field.key] = value;
    });

    setForm(values);
    setShowForm(true);
  };

  const saveItem = async event => {
    event.preventDefault();

    try {
      const payload = { ...form };

      if (section === 'carts') {
        const cartName = String(payload.cartName || '').trim();
        const cartItems = String(payload.itemsText || '')
          .split(/\r?\n/)
          .map(item => item.trim())
          .filter(Boolean);

        if (!cartName || cartItems.length === 0) {
          throw new Error('Enter a cart name and at least one item.');
        }

        payload.itemsText = [cartName, ...cartItems].join('\n');
        delete payload.cartName;
      }

      currentConfig.fields.forEach(field => {
        if (field.type === 'number' || field.type === 'recipe') {
          if (payload[field.key] !== '') {
            payload[field.key] = Number(payload[field.key]);
          }
        }
      });

      if (section === 'shopping-list') {
        payload.is_purchased = Boolean(payload.is_purchased);
      }

      if (section === 'notifications') {
        payload.read = Boolean(payload.read);
      }

      if (section === 'reviews') {
        payload.rating = Number(payload.rating);
      }

      if (section === 'activity-logs' && payload.detailsText) {
        try {
          payload.details = JSON.parse(payload.detailsText);
          delete payload.detailsText;
        } catch {
          payload.details = { note: payload.detailsText };
          delete payload.detailsText;
        }
      }

      const path = `/${currentConfig.path}${editing ? `/${editing}` : ''}`;

      await call(path, {
        method: editing ? 'PUT' : 'POST',
        body: JSON.stringify(payload)
      });

      setShowForm(false);
      setEditing(null);
      setForm({});
      notify(editing ? 'Information updated successfully.' : 'Item added successfully.');
      await loadRows();
      if (section === 'recipes') await loadDashboard();
    } catch (err) {
      notify(err.message, true);
    }
  };

  const deleteItem = async id => {
    if (!window.confirm('Are you sure you want to delete this item?')) return;

    try {
      await call(`/${currentConfig.path}/${id}`, { method: 'DELETE' });
      notify('Item deleted successfully.');
      await loadRows();
      if (section === 'recipes') await loadDashboard();
    } catch (err) {
      notify(err.message, true);
    }
  };

  const confirmPlan = async (id, forceRollback = false) => {
    const question = forceRollback
      ? 'Run the rollback demonstration? The transaction should be cancelled.'
      : 'Confirm this meal plan?';

    if (!window.confirm(question)) return;

    try {
      const suffix = forceRollback ? '?forceRollback=true' : '';
      await call(`/meal-plans/${id}/confirm${suffix}`, { method: 'POST' });
      notify(forceRollback
        ? 'Rollback test completed. Check the meal plan status and activity history.'
        : 'Meal plan confirmed and synchronized successfully.');
      await loadRows();
    } catch (err) {
      notify(err.message, true);
      await loadRows();
    }
  };

  const goTo = key => {
    setSection(key);
    setShowForm(false);
    setEditing(null);
    setMessage('');
    setError('');
  };

  if (!token || !user) {
    return (
      <div className="auth-page">
        <div className="auth-decoration auth-decoration-one" />
        <div className="auth-decoration auth-decoration-two" />

        <div className="auth-card">
          <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', width: '100%', margin: '0 auto 12px', padding: 0, background: 'transparent', border: 0, boxShadow: 'none' }}><MealPlannerLogo size={190} /></div>
          <p className="eyebrow">YOUR PERSONAL FOOD ORGANIZER</p>
          <p className="auth-description" style={{ marginTop: 8 }}>
            Plan your meals, organize your recipes and make shopping easier.
          </p>

          <div className="auth-tabs">
            <button
              className={authMode === 'login' ? 'active' : ''}
              onClick={() => setAuthMode('login')}
              type="button"
            >
              Sign in
            </button>
            <button
              className={authMode === 'register' ? 'active' : ''}
              onClick={() => setAuthMode('register')}
              type="button"
            >
              Create account
            </button>
          </div>

          <form onSubmit={handleAuth} className="auth-form">
            {authMode === 'register' && (
              <label>
                Full name
                <input
                  value={authForm.name}
                  onChange={e => setAuthForm({ ...authForm, name: e.target.value })}
                  placeholder="Your name"
                  required
                />
              </label>
            )}

            <label>
              Email address
              <input
                type="email"
                value={authForm.email}
                onChange={e => setAuthForm({ ...authForm, email: e.target.value })}
                placeholder="name@example.com"
                required
              />
            </label>

            <label>
              Password
              <input
                type="password"
                value={authForm.password}
                onChange={e => setAuthForm({ ...authForm, password: e.target.value })}
                placeholder="At least 8 characters"
                minLength="8"
                required
              />
            </label>

            {error && <div className="alert alert-error">{error}</div>}

            <button className="primary-button full-button" type="submit">
              {authMode === 'login' ? 'Sign in to your account' : 'Create my account'}
            </button>
          </form>

          <p className="auth-footer">A simpler way to plan your meals.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="app-shell">
      <aside className="sidebar">
        <div className="sidebar-brand">
          <div>
            <strong>Meal Planner</strong>
            <span>PERSONAL ORGANIZER</span>
          </div>
        </div>

        <div className="sidebar-section-label">WORKSPACE</div>

        <nav className="main-nav">
          <button className={section === 'dashboard' ? 'nav-item active' : 'nav-item'} onClick={() => goTo('dashboard')}>
            <span className="nav-icon">⌂</span> Dashboard
          </button>
          <button className={section === 'recipes' ? 'nav-item active' : 'nav-item'} onClick={() => goTo('recipes')}>
            <span className="nav-icon">▤</span> My Recipes
          </button>
          <button className={section === 'ingredients' ? 'nav-item active' : 'nav-item'} onClick={() => goTo('ingredients')}>
            <span className="nav-icon">◈</span> Ingredients
          </button>
          <button className={section === 'recipe-ingredients' ? 'nav-item active' : 'nav-item'} onClick={() => goTo('recipe-ingredients')}>
            <span className="nav-icon">⊕</span> Recipe Ingredients
          </button>
          <button className={section === 'meal-plans' ? 'nav-item active' : 'nav-item'} onClick={() => goTo('meal-plans')}>
            <span className="nav-icon">▦</span> Meal Planner
          </button>
          <button className={section === 'shopping-list' ? 'nav-item active' : 'nav-item'} onClick={() => goTo('shopping-list')}>
            <span className="nav-icon">☷</span> Shopping List
          </button>
        </nav>

        <div className="sidebar-section-label secondary-label">PERSONAL SPACE</div>

        <nav className="main-nav">
          <button className={section === 'reviews' ? 'nav-item active' : 'nav-item'} onClick={() => goTo('reviews')}>
            <span className="nav-icon">☆</span> Recipe Reviews
          </button>
          <button className={section === 'carts' ? 'nav-item active' : 'nav-item'} onClick={() => goTo('carts')}>
            <span className="nav-icon">▣</span> Shopping Carts
          </button>
          <button className={section === 'notifications' ? 'nav-item active' : 'nav-item'} onClick={() => goTo('notifications')}>
            <span className="nav-icon">♧</span> Notifications
          </button>
          <button className={section === 'activity-logs' ? 'nav-item active' : 'nav-item'} onClick={() => goTo('activity-logs')}>
            <span className="nav-icon">◷</span> Activity History
          </button>
        </nav>

        <div className="sidebar-bottom">
          <div className="profile-mini">
            <div className="avatar">{(user.name || user.email || 'U').charAt(0).toUpperCase()}</div>
            <div className="profile-text">
              <strong>{user.name || 'User'}</strong>
            </div>
          </div>
          <button className="logout-button" onClick={logout}>↪ Sign out</button>
        </div>
      </aside>

      <main className="main-content">
        <header className="topbar">
          <div>
            <span className="topbar-overline">MEAL PLANNER WORKSPACE</span>
            <h2>{section === 'dashboard' ? 'Welcome back' : currentConfig?.title || 'Recipe Ingredients'}</h2>
          </div>
          <div className="topbar-right">
            <span className="today-label">{new Date().toLocaleDateString()}</span>
            <div className="avatar top-avatar">{(user.name || 'U').charAt(0).toUpperCase()}</div>
          </div>
        </header>

        {message && <div className="alert alert-success">{message}</div>}
        {error && <div className="alert alert-error">{error}</div>}

        {section === 'dashboard' && (
          <Dashboard
            user={user}
            dashboard={dashboard}
            onNavigate={goTo}
            recipes={recipes}
          />
        )}

        {currentConfig && (
          <section className="content-section">
            <div className="section-heading">
              <div>
                <p className="eyebrow">MANAGE YOUR SPACE</p>
                <h1>{currentConfig.title}</h1>
                <p className="section-description">{currentConfig.subtitle}</p>
              </div>
              <button className="primary-button" onClick={openCreate}>
                <span>＋</span> Add new
              </button>
            </div>

            {showForm && (
              <div className="form-card">
                <div className="form-card-heading">
                  <div>
                    <h3>{editing ? 'Edit information' : 'Add a new item'}</h3>
                    <p>Complete the fields below and save your changes.</p>
                  </div>
                  <button className="icon-button" onClick={() => setShowForm(false)} type="button">×</button>
                </div>

                <form onSubmit={saveItem} className="data-form">
                  {currentConfig.fields.map(field => (
                    <label key={field.key} className={field.type === 'textarea' ? 'wide-field' : ''}>
                      {field.label}
                      {field.type === 'textarea' ? (
                        <textarea
                          value={form[field.key] ?? ''}
                          required={field.required}
                          rows="3"
                          onChange={e => setForm({ ...form, [field.key]: e.target.value })}
                        />
                      ) : field.type === 'select' ? (
                        <select
                          value={form[field.key] ?? ''}
                          onChange={e => setForm({ ...form, [field.key]: e.target.value })}
                        >
                          <option value="">Select an option</option>
                          {field.options.map(option => <option key={option} value={option}>{option}</option>)}
                        </select>
                      ) : field.type === 'recipe' ? (
                        <select
                          value={form[field.key] ?? ''}
                          required={field.required}
                          onChange={e => setForm({ ...form, [field.key]: e.target.value })}
                        >
                          <option value="">Choose a recipe</option>
                          {recipes.map(recipe => (
                            <option key={recipe.id} value={recipe.id}>{recipe.title}</option>
                          ))}
                        </select>
                      ) : field.type === 'boolean' ? (
                        <select
                          value={String(Boolean(form[field.key]))}
                          onChange={e => setForm({ ...form, [field.key]: e.target.value === 'true' })}
                        >
                          <option value="false">No</option>
                          <option value="true">Yes</option>
                        </select>
                      ) : (
                        <input
                          type={field.type || 'text'}
                          value={form[field.key] ?? ''}
                          required={field.required}
                          min={field.key === 'rating' ? 1 : undefined}
                          max={field.key === 'rating' ? 5 : undefined}
                          onChange={e => setForm({ ...form, [field.key]: e.target.value })}
                        />
                      )}
                    </label>
                  ))}

                  <div className="form-actions wide-field">
                    <button type="button" className="secondary-button" onClick={() => setShowForm(false)}>Cancel</button>
                    <button type="submit" className="primary-button">{editing ? 'Save changes' : 'Create item'}</button>
                  </div>
                </form>
              </div>
            )}

            <div className="list-heading">
              <div>
                <h3>Your items</h3>
                <span>{rows.length} {rows.length === 1 ? 'item' : 'items'}</span>
              </div>
            </div>

            {loading ? (
              <div className="empty-state">Loading your information...</div>
            ) : rows.length === 0 ? (
              <div className="empty-state">
                <div className="empty-icon">＋</div>
                <h3>Nothing here yet</h3>
                <p>Add your first item to get started.</p>
                <button className="secondary-button" onClick={openCreate}>Add your first item</button>
              </div>
            ) : (
              <div className="item-grid">
                {rows.map(row => (
                  <DataCard
                    key={row.id || row._id}
                    row={row}
                    section={section}
                    recipes={recipes}
                    onEdit={() => openEdit(row)}
                    onDelete={() => deleteItem(row.id || row._id)}
                    onConfirm={() => confirmPlan(row.id)}
                    onRollback={() => confirmPlan(row.id, true)}
                  />
                ))}
              </div>
            )}
          </section>
        )}

        {section === 'recipe-ingredients' && (
          <RecipeIngredients call={call} recipes={recipes} notify={notify} />
        )}
      </main>
    </div>
  );
}

function Dashboard({ user, dashboard, onNavigate, recipes }) {
  const cards = [
    { title: 'My Recipes', value: dashboard.recipes, icon: '▤', section: 'recipes', description: 'Recipes saved' },
    { title: 'Ingredients', value: dashboard.ingredients, icon: '◈', section: 'ingredients', description: 'Ingredients available' },
    { title: 'Meal Plans', value: dashboard.plans, icon: '▦', section: 'meal-plans', description: 'Meals organized' },
    { title: 'To Buy', value: dashboard.shopping, icon: '☷', section: 'shopping-list', description: 'Items not purchased' }
  ];

  return (
    <section className="content-section">
      <div className="welcome-panel" style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 24,
        padding: '30px 34px', minHeight: 190, borderRadius: 22,
        background: 'linear-gradient(120deg, #F3F7EF 0%, #E7F0E4 58%, #F8F3E8 100%)',
        border: '1px solid #DCE8D8', boxShadow: '0 12px 30px rgba(45, 83, 56, 0.07)',
        position: 'relative', overflow: 'hidden'
      }}>

         <div style={{
          flex: '1 1 0',
          minWidth: 0,
          position: 'relative',
          zIndex: 1
        }}>
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: 9,
            marginBottom: 14
          }}>
            
            <span style={{
  color: '#52765A',
  fontSize: 10,
  fontWeight: 800,
  letterSpacing: '1.8px',
  textTransform: 'uppercase'
}}>
  YOUR PERSONAL FOOD ORGANIZER
</span>
          </div>

          <p style={{
            margin: 0,
            maxWidth: 420,
            fontSize: 'clamp(16px, 1.6vw, 20px)',
            lineHeight: 1.5,
            fontWeight: 600,
            letterSpacing: '-0.3px',
            color: '#294B35'
          }}>
            Plan your weekly meals and organize your shopping list.
          </p>
        </div>       

  <div style={{
    flex: '0 0 auto',
    width: 122,
    maxWidth: '30%',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    padding: 7,
    borderRadius: 18,
    background: '#FFFFFFA8',
    boxShadow: '0 8px 22px rgba(45, 83, 56, 0.08)',
    position: 'relative',
    zIndex: 1
  }}>
    <MealPlannerLogo size={108} />
  </div>

  <div aria-hidden="true" style={{
    position: 'absolute',
    width: 190,
    height: 190,
    borderRadius: '50%',
    right: 70,
    top: -125,
    background: 'rgba(255,255,255,0.28)',
    pointerEvents: 'none'
  }} />
</div>

      <div className="stats-grid">
        {cards.map(card => (
          <button className="stat-card" key={card.title} onClick={() => onNavigate(card.section)}>
            <div className="stat-card-top">
              <span className="stat-icon">{card.icon}</span>
              <span className="stat-arrow">↗</span>
            </div>
            <strong>{card.value}</strong>
            <span className="stat-title">{card.title}</span>
            <span className="stat-description">{card.description}</span>
          </button>
        ))}
      </div>

      <div className="dashboard-lower">
        <div className="panel-card">
          <div className="panel-heading">
            <div>
              <h3>Quick actions</h3>
              <p>Go directly to the tools you need.</p>
            </div>
          </div>
          <div className="quick-actions">
            <button onClick={() => onNavigate('recipes')}><span>＋</span><div><strong>Add a recipe</strong><small>Create something new</small></div></button>
            <button onClick={() => onNavigate('meal-plans')}><span>▦</span><div><strong>Plan a meal</strong><small>Organize your week</small></div></button>
            <button onClick={() => onNavigate('shopping-list')}><span>☷</span><div><strong>Shopping list</strong><small>Check what you need</small></div></button>
          </div>
        </div>

        <div className="panel-card">
          <div className="panel-heading">
            <div>
              <h3>Recent recipes</h3>
              <p>Your latest saved recipes.</p>
            </div>
            <button className="text-button" onClick={() => onNavigate('recipes')}>View all</button>
          </div>
          {recipes.slice(0, 4).length === 0 ? (
            <p className="muted-text">Your recipes will appear here.</p>
          ) : (
            <div className="recent-list">
              {recipes.slice(0, 4).map(recipe => (
                <div className="recent-item" key={recipe.id}>
                  <span className="recent-icon">✦</span>
                  <div><strong>{recipe.title}</strong><small>{recipe.prep_minutes ? `${recipe.prep_minutes} minutes` : 'Recipe'}</small></div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

function DataCard({ row, section, recipes, onEdit, onDelete, onConfirm, onRollback }) {
  const recipeName = id => recipes.find(recipe => Number(recipe.id) === Number(id))?.title || `Recipe #${id}`;

  const cartLines = section === 'carts'
    ? String(row.itemsText || '').split(/\r?\n/).map(item => item.trim()).filter(Boolean)
    : [];
  const cartTitle = cartLines.length > 1 ? cartLines[0] : 'Shopping cart';
  const cartItems = cartLines.length > 1 ? cartLines.slice(1) : cartLines;

  const action = String(row.action || '').toUpperCase();
  const isRollback = action.includes('ROLLBACK');
  const isConfirmed = action.includes('CONFIRMED');
  const activityTitle = isRollback
    ? 'Transaction rolled back'
    : isConfirmed
      ? 'Meal plan confirmed'
      : action.replaceAll('_', ' ').toLowerCase().replace(/^./, letter => letter.toUpperCase());

  const notificationTitle = row.message || 'Application notification';

  const title =
    section === 'carts' ? cartTitle :
    section === 'notifications' ? notificationTitle :
    section === 'activity-logs' ? activityTitle :
    section === 'reviews' ? recipeName(row.recipeId) :
    row.title ||
    row.name ||
    row.item_name ||
    row.message ||
    row.action ||
    row.itemsText?.split('\n')[0] ||
    row.meal_type ||
    'Saved item';

  const details = [];

  if (section === 'recipes') {
    if (row.description) details.push(row.description);
    if (row.prep_minutes) details.push(`${row.prep_minutes} min preparation`);
    if (row.servings) details.push(`${row.servings} servings`);
  } else if (section === 'ingredients') {
    if (row.unit) details.push(`Unit: ${row.unit}`);
  } else if (section === 'meal-plans') {
    details.push(`Date: ${String(row.plan_date).slice(0, 10)}`);
    details.push(`Recipe: ${recipeName(row.recipe_id)}`);
  } else if (section === 'shopping-list') {
    details.push(`Quantity: ${row.quantity ?? 1} ${row.unit || ''}`);
  } else if (section === 'reviews') {
    details.push(`Rating: ${row.rating}/5`);
    if (row.comment) details.push(row.comment);
  } else if (section === 'notifications') {
    details.push(row.type === 'success' ? 'Your meal plan was successfully confirmed.' :
      row.type === 'warning' ? 'This notification requires your attention.' :
      'Application update');
  } else if (section === 'activity-logs') {
    const entityLabel = row.entity || 'meal plan';
    const entityNumber = row.entityId ? ` #${row.entityId}` : '';
    details.push(isRollback
      ? `The confirmation of ${entityLabel}${entityNumber} was cancelled. No SQL changes were committed.`
      : isConfirmed
        ? `${entityLabel}${entityNumber} was confirmed and the transaction was committed.`
        : `${entityLabel}${entityNumber} activity was recorded.`);
    if (row.details?.reason) details.push(`Reason: ${row.details.reason}`);
  }

  const status = section === 'meal-plans'
    ? row.status
    : section === 'shopping-list'
      ? (row.is_purchased ? 'Purchased' : 'To buy')
      : section === 'notifications'
        ? (row.read ? 'Read' : 'Unread')
        : section === 'activity-logs'
          ? (isRollback ? 'Rolled back' : isConfirmed ? 'Successful' : 'Recorded')
          : null;

  const categoryLabel = section === 'reviews'
    ? 'RECIPE REVIEW'
    : section === 'activity-logs'
      ? 'ACTIVITY RECORD'
      : section === 'notifications'
      ? 'NOTIFICATION'
      : section.replace('-', ' ');

  return (
    <article className={`item-card ${section === 'notifications' ? 'notification-card' : ''} ${section === 'activity-logs' ? 'activity-card' : ''} ${section === 'carts' ? 'cart-card' : ''}`}>
      <div className="item-card-top">
        <span className="item-category">{categoryLabel}</span>
        {status && (
          <span className={`status-pill ${
            status === 'confirmed' || status === 'Purchased' || status === 'Read' || status === 'Successful'
              ? 'status-good'
              : status === 'Rolled back'
                ? 'status-warning'
                : ''
          }`}>{status}</span>
        )}
      </div>

      <h3>{section === 'notifications' ? `🔔 ${title}` : section === 'activity-logs' ? `${isRollback ? '↩' : isConfirmed ? '✓' : '•'} ${title}` : title}</h3>

      {section === 'carts' ? (
        <div className="cart-contents">
          <p className="muted-text">Items in this cart</p>
          {cartItems.length ? (
            <ul>{cartItems.map((item, index) => <li key={`${item}-${index}`}>{item}</li>)}</ul>
          ) : <p>No items added yet.</p>}
        </div>
      ) : (
        <div className="item-details">
          {details.filter(Boolean).map((detail, index) => <p key={index}>{detail}</p>)}
        </div>
      )}

      <div className="item-actions">
        {section === 'meal-plans' && row.status !== 'confirmed' && (
          <button className="confirm-button" onClick={onConfirm}>Confirm plan</button>
        )}
        {section === 'meal-plans' && row.status !== 'confirmed' && (
          <button className="test-button" onClick={onRollback}>Test rollback</button>
        )}
        <button className="secondary-button small-button" onClick={onEdit}>Edit</button>
        <button className="delete-button" onClick={onDelete}>Delete</button>
      </div>
    </article>
  );
}

function RecipeIngredients({ call, recipes, notify }) {
  const [ingredients, setIngredients] = useState([]);
  const [links, setLinks] = useState([]);
  const [recipeId, setRecipeId] = useState('');
  const [ingredientId, setIngredientId] = useState('');
  const [quantity, setQuantity] = useState('1');
  const [editing, setEditing] = useState(null);
  const [editQuantity, setEditQuantity] = useState('1');

  const load = async () => {
    try {
      const [ingredientData, linkData] = await Promise.all([
        call('/ingredients'),
        call('/recipe-ingredients')
      ]);
      setIngredients(ingredientData);
      setLinks(linkData);
    } catch (err) {
      notify(err.message, true);
    }
  };

  useEffect(() => { load(); }, []);

  const save = async event => {
    event.preventDefault();
    try {
      await call('/recipe-ingredients', {
        method: 'POST',
        body: JSON.stringify({
          recipe_id: Number(recipeId),
          ingredient_id: Number(ingredientId),
          quantity: Number(quantity)
        })
      });
      setRecipeId('');
      setIngredientId('');
      setQuantity('1');
      notify('Ingredient linked to recipe.');
      await load();
    } catch (err) {
      notify(err.message, true);
    }
  };

  const update = async id => {
    try {
      await call(`/recipe-ingredients/${id}`, {
        method: 'PUT',
        body: JSON.stringify({ quantity: Number(editQuantity) })
      });
      setEditing(null);
      notify('Quantity updated.');
      await load();
    } catch (err) {
      notify(err.message, true);
    }
  };

  const remove = async id => {
    if (!window.confirm('Remove this ingredient from the recipe?')) return;
    try {
      await call(`/recipe-ingredients/${id}`, { method: 'DELETE' });
      notify('Ingredient removed.');
      await load();
    } catch (err) {
      notify(err.message, true);
    }
  };

  const recipeName = id => recipes.find(item => Number(item.id) === Number(id))?.title || `Recipe #${id}`;
  const ingredientName = id => ingredients.find(item => Number(item.id) === Number(id))?.name || `Ingredient #${id}`;

  return (
    <section className="content-section">
      <div className="section-heading">
        <div>
          <p className="eyebrow">RECIPE COMPOSITION</p>
          <h1>Recipe Ingredients</h1>
          <p className="section-description">Connect ingredients to your recipes and manage quantities.</p>
        </div>
      </div>

      <div className="form-card">
        <div className="form-card-heading">
          <div><h3>Add an ingredient to a recipe</h3><p>Select a recipe, an ingredient and its quantity.</p></div>
        </div>
        <form className="data-form" onSubmit={save}>
          <label>
            Recipe
            <select value={recipeId} onChange={e => setRecipeId(e.target.value)} required>
              <option value="">Choose a recipe</option>
              {recipes.map(recipe => <option key={recipe.id} value={recipe.id}>{recipe.title}</option>)}
            </select>
          </label>
          <label>
            Ingredient
            <select value={ingredientId} onChange={e => setIngredientId(e.target.value)} required>
              <option value="">Choose an ingredient</option>
              {ingredients.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}
            </select>
          </label>
          <label>
            Quantity
            <input type="number" min="0.01" step="0.01" value={quantity} onChange={e => setQuantity(e.target.value)} required />
          </label>
          <div className="form-actions wide-field">
            <button className="primary-button" type="submit">Add to recipe</button>
          </div>
        </form>
      </div>

      <div className="list-heading"><div><h3>Ingredient associations</h3><span>{links.length} associations</span></div></div>

      {links.length === 0 ? (
        <div className="empty-state"><h3>No ingredients linked yet</h3><p>Add an ingredient to one of your recipes above.</p></div>
      ) : (
        <div className="item-grid">
          {links.map(link => (
            <article className="item-card" key={link.id}>
              <span className="item-category">RECIPE COMPOSITION</span>
              <h3>{ingredientName(link.ingredient_id)}</h3>
              <p className="association-recipe">Recipe: {recipeName(link.recipe_id)}</p>
              {editing === link.id ? (
                <div className="inline-edit">
                  <input type="number" min="0.01" step="0.01" value={editQuantity} onChange={e => setEditQuantity(e.target.value)} />
                  <button className="primary-button small-button" onClick={() => update(link.id)}>Save</button>
                  <button className="secondary-button small-button" onClick={() => setEditing(null)}>Cancel</button>
                </div>
              ) : (
                <p>Quantity: {link.quantity}</p>
              )}
              <div className="item-actions">
                <button className="secondary-button small-button" onClick={() => { setEditing(link.id); setEditQuantity(String(link.quantity)); }}>Edit quantity</button>
                <button className="delete-button" onClick={() => remove(link.id)}>Remove</button>
              </div>
            </article>
          ))}
        </div>
      )}
    </section>
  );
}

export default App;
